function safeDateValue(v){if(!v)return '';let x=String(v).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(x))return x;let d=new Date(x);if(Number.isNaN(d.getTime()))return '';return d.toISOString().slice(0,10)}
function formatDateDO(v){let x=safeDateValue(v);if(!x)return '—';let [y,m,d]=x.split('-');return `${d}/${m}/${y}`}
