async function refreshMessageBell(){if(!session?.token)return [];let notices=[];try{const [mc,ev,br]=await Promise.all([api('messages.contacts').catch(()=>({items:[]})),api('events.list').catch(()=>({items:[]})),api('birds.list').catch(()=>({items:[]}))]);const contacts=Array.isArray(mc.items)?mc.items:[];contacts.filter(x=>Number(x.unread||0)>0).forEach(x=>notices.push({type:'message',icon:'💬',title:`Mensaje de ${x.name||x.email||'usuario'}`,text:`${Number(x.unread||0)} mensaje(s) sin leer`,route:'messages',time:x.updatedAt||''}));let today=new Date();today.setHours(0,0,0,0);(ev.items||[]).forEach(x=>{let d=safeDateValue(x.date);if(!d)return;let dt=new Date(d+'T00:00:00'),days=Math.round((dt-today)/86400000);if(days>=0&&days<=7)notices.push({type:'event',icon:'📅',title:days===0?'Evento hoy':`Evento en ${days} día(s)`,text:x.place||x.result||'Evento programado',route:'events',time:d})});(br.items||[]).filter(x=>!safeDateValue(x.birthDate)).slice(0,5).forEach(x=>notices.push({type:'bird',icon:'🐓',title:'Ficha por completar',text:`${x.name||x.plate||'Ejemplar'} no tiene fecha de nacimiento válida`,route:'birds',time:x.updatedAt||''}));const seen=seenNotificationKeys();notificationItems=notices.filter(n=>!seen.has(notificationKey(n))).sort((a,b)=>String(b.time||'').localeCompare(String(a.time||'')));const bell=document.getElementById('messageBell'),count=document.getElementById('messageBellCount');if(bell)bell.classList.toggle('has-unread',notificationItems.length>0);if(count){count.textContent=notificationItems.length>99?'99+':String(notificationItems.length);count.classList.toggle('hidden',notificationItems.length<1)}return notificationItems}catch(e){return []}}
function toggleNotificationCenter(){let old=document.getElementById('notificationCenter');if(old){old.remove();return}let box=document.createElement('div');box.id='notificationCenter';box.className='notification-center';box.innerHTML=`<div class="notification-head"><div><b>Notificaciones</b><small>Actividad general de CryApp</small></div><div class="notification-head-actions"><button id="markNotificationsRead" class="notification-read-all">Marcar leídas</button><button id="closeNotifications">×</button></div></div><div class="notification-list">${notificationItems.length?notificationItems.map((n,i)=>`<button class="notification-item" data-notice="${i}"><span>${n.icon}</span><div><b>${esc(n.title)}</b><small>${esc(n.text)}</small></div></button>`).join(''):'<div class="empty">No hay notificaciones pendientes.</div>'}</div>`;document.body.appendChild(box);box.querySelector('#closeNotifications').onclick=()=>box.remove();box.querySelector('#markNotificationsRead')?.addEventListener('click',markAllNotificationsRead);box.onclick=e=>{let b=e.target.closest('[data-notice]');if(!b)return;let n=notificationItems[Number(b.dataset.notice)];box.remove();if(n?.route)route(n.route)}}
