// Adaptador TrueNAS: la web y la API comparten origen mediante Nginx.
function tnBird(b){return {birdId:b.id,plate:b.codigo||'',name:b.nombre||'',sex:(b.sexo||'').toLowerCase()==='hembra'?'Gallina':'Gallo',breed:b.raza||'',plumage:b.color||'',plateColor:b.color_placa||'',farm:b.criadero||'',comb:b.tipo_cresta||'',legColor:b.color_patas||'',birthDate:b.fecha_nacimiento||'',photoUrl:b.foto||'',fatherId:b.padre_id||'',motherId:b.madre_id||'',crossNumber:b.numero_cruce||'',status:b.estado||'activo',notes:b.observaciones||'',createdAt:b.fecha_registro||'',updatedAt:b.fecha_registro||''}}
function tnUser(u){if(!u)return {};return {userId:u.id||u.userId,name:u.nombre||u.name||'',email:u.correo||u.email||'',role:u.rol||u.role||'usuario',farmName:u.criadero??u.farmName??'',phone:u.telefono??u.phone??'',photoUrl:u.foto||u.photoUrl||''}}
async function tnRequest(path,method='GET',body){
 const headers={'Accept':'application/json'};
 if(body!==undefined)headers['Content-Type']='application/json';
 if(session?.token)headers.Authorization='Bearer '+session.token;
 let res;
 try{res=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});}catch(e){throw Error('No se pudo conectar con la API de TrueNAS. Comprueba el proxy /api.');}
 const j=await res.json().catch(()=>({}));
 if(!res.ok)throw Error(j.error||j.message||('Error HTTP '+res.status));
 return j;
}
async function api(action,data={}){
 switch(action){
 case 'subscriptions.status':return await tnRequest('/api/subscriptions/status');
 case 'subscriptions.plans':return await tnRequest('/api/subscriptions/plans');
 case 'subscriptions.requests':return await tnRequest('/api/subscriptions/requests');
 case 'subscriptions.request':return await tnRequest('/api/subscriptions/requests','POST',data);
 case 'auth.login':{
   const x=await tnRequest('/api/auth/login','POST',{correo:data.email,password:data.password});
   if(!x.token)throw Error('La API no devolvió token');
   return {ok:true,token:x.token,user:tnUser(x.user||x.usuario)};
 }
 case 'auth.register':{
   const x=await tnRequest('/api/auth/register','POST',{nombre:data.name,correo:data.email,password:data.password});
   return {ok:true,...x};
 }
 case 'auth.me':{
   const x=await tnRequest('/api/auth/me');
   return {ok:true,user:tnUser(x.user||x.usuario)};
 }
case 'auth.backup':return await tnRequest('/api/auth/backup');
 case 'auth.delete':return await tnRequest('/api/auth/delete-account','POST',data);
  case 'profile.save':{
   const profile={...(data.profile||{})};
   if(profile.photo){
     const photo=profile.photo;
     if(typeof photo==='object' && typeof photo.base64==='string' && /^image\/(jpeg|png|webp)$/.test(photo.mimeType||'')){
       profile.photo='data:'+photo.mimeType+';base64,'+photo.base64;
     }else if(typeof photo!=='string')throw Error('Formato de fotografía no compatible');
   }
   const x=await tnRequest('/api/auth/profile','PATCH',{profile});
   return {ok:true,user:tnUser(x.usuario||x.user)};
 }
 case 'auth.logout':return {ok:true};
 case 'birds.list':{
   const x=await tnRequest('/api/ejemplares');
   return {ok:true,items:(x.ejemplares||[]).map(tnBird)};
 }
 case 'birds.save':{
   const b=data.bird||{};
   const fields={codigo:b.plate||null,nombre:b.name||'',sexo:/gallina|hembra/i.test(b.sex||'')?'hembra':'macho',raza:b.breed||null,color:b.plumage||null,color_placa:b.plateColor||null,criadero:b.farm||null,tipo_cresta:b.comb||null,color_patas:b.legColor||null,fecha_nacimiento:b.birthDate||null,padre_id:b.fatherId||null,madre_id:b.motherId||null,numero_cruce:b.crossNumber||null};
   const id=b.birdId;
   const x=await tnRequest(id?'/api/ejemplares/'+encodeURIComponent(id):'/api/ejemplares',id?'PATCH':'POST',fields);
   return {ok:true,birdId:x.ejemplar?.id,bird:tnBird(x.ejemplar||{})};
 }
 case 'birds.photo':{
   const x=await tnRequest('/api/ejemplares/'+encodeURIComponent(data.birdId)+'/foto','POST',{photo:data.photo});
   return {ok:true,photoSaved:x.photoSaved===true,photoUrl:x.photoUrl};
 }
 case 'birds.delete':return await tnRequest('/api/ejemplares/'+encodeURIComponent(data.birdId),'DELETE');
 case 'events.list':return await tnRequest('/api/modules/events');
 case 'events.save':return await tnRequest('/api/modules/events','POST',{item:data.event});
 case 'events.delete':return await tnRequest('/api/modules/events/'+encodeURIComponent(data.eventId),'DELETE');
 case 'crosses.list':return await tnRequest('/api/modules/crosses');
 case 'crosses.save':return await tnRequest('/api/modules/crosses','POST',{item:data.cross});
 case 'stats.summary':return await tnRequest('/api/modules/stats');
 case 'dashboard':{const [b,e,m]=await Promise.all([api('birds.list'),api('events.list'),api('market.feed')]);return {ok:true,counts:{birds:b.items.length,events:e.items.length,market:m.items.length}};}
 case 'market.feed':return await tnRequest('/api/modules/market');
 case 'market.save':{const r=await tnRequest('/api/modules/market','POST',{item:data.listing});return {...r,listingId:r.id};}
 case 'market.update':return await tnRequest('/api/modules/market/'+encodeURIComponent(data.listingId),'PATCH',{item:data.listing});
 case 'market.delete':return await tnRequest('/api/modules/market/'+encodeURIComponent(data.listingId),'DELETE');
 case 'market.status':return await tnRequest('/api/modules/market/'+encodeURIComponent(data.listingId),'PATCH',{status:data.status});
 case 'breeding.rankings':{const b=(await api('birds.list')).items;return {ok:true,items:b.map(x=>({...x,children:b.filter(y=>y.fatherId===x.birdId||y.motherId===x.birdId).length,wins:0,effectiveness:0})).filter(x=>x.children).map(x=>({name:x.name,children:x.children,wins:x.wins,effectiveness:x.effectiveness}))};}
 case 'genealogy.tree':{const b=(await api('birds.list')).items;return {ok:true,tree:b.find(x=>x.birdId===data.birdId)||null};}
 case 'messages.presence':return await tnRequest('/api/modules/presence','POST',{});
 case 'messages.contacts':return await tnRequest('/api/modules/contacts');
 case 'messages.thread':return await tnRequest('/api/modules/thread/'+encodeURIComponent(data.peerId));
 case 'messages.send':return await tnRequest('/api/modules/messages','POST',{recipientId:data.recipientId,text:data.text});
 case 'messages.read':return await tnRequest('/api/modules/read/'+encodeURIComponent(data.peerId),'POST',{});
 case 'messages.delete':return await tnRequest('/api/modules/messages/'+encodeURIComponent(data.messageId),'DELETE');
 default:throw Error('El módulo «'+action+'» todavía no tiene endpoint en la API TrueNAS. No se guardó ningún cambio.');
 }
}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// V1.7.6 FIX — convierte/optimiza archivos de imagen antes de enviarlos al GS.
// Devuelve el formato que CryApp_API.gs espera: {base64,mimeType,fileName}.
async function file64(file){
  if(!file)return null;
  if(!file.type||!file.type.startsWith('image/'))throw Error('Selecciona una imagen JPG, PNG o WebP.');
  const MAX_INPUT=15*1024*1024;
  if(file.size>MAX_INPUT)throw Error('La fotografía es demasiado grande. Máximo 15 MB.');
  const readDataURL=f=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result||''));r.onerror=()=>no(Error('No se pudo leer la fotografía.'));r.readAsDataURL(f)});
  try{
    const url=URL.createObjectURL(file);
    const img=await new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=()=>no(Error('No se pudo abrir la fotografía.'));i.src=url});
    const max=1280, scale=Math.min(1,max/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));
    const w=Math.max(1,Math.round((img.naturalWidth||img.width)*scale)),h=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));
    const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.drawImage(img,0,0,w,h);URL.revokeObjectURL(url);
    const mime='image/jpeg';
    const data=c.toDataURL(mime,0.82);
    return {base64:data.split(',')[1]||'',mimeType:mime,fileName:(file.name||'foto').replace(/\.[^.]+$/,'')+'.jpg'};
  }catch(err){
    const data=await readDataURL(file);
    return {base64:data.split(',')[1]||'',mimeType:file.type||'image/jpeg',fileName:file.name||'foto.jpg'};
  }
}
function showServerSetup(){auth.classList.add('hidden');app.classList.add('hidden');let box=document.querySelector('#serverSetup');if(!box){box=document.createElement('section');box.id='serverSetup';box.className='auth';box.innerHTML=`<div class="auth-card server-card"><img src="assets/CryApp_Logo.png" class="logo"><h1>Conectar CryApp</h1><p>Conecta el servidor central para sincronizar toda la plataforma.</p><form id="serverForm"><input id="serverUrl" type="url" placeholder="https://script.google.com/macros/s/.../exec" required><button>Conectar servidor</button></form><small id="serverStatus"></small></div>`;document.body.appendChild(box)}serverForm.onsubmit=async e=>{e.preventDefault();let u=serverUrl.value.trim();serverStatus.textContent='Comprobando…';try{let j=await(await fetch(u)).json();if(!j.ok||j.product!=='CryApp API')throw 0;localStorage.setItem('cryapp_api_url',u);C.API_URL=u;location.reload()}catch{serverStatus.textContent='URL no válida o implementación no disponible.'}}}
