function paintUser(){let u=session?.user||{};const emailEl=document.getElementById('userEmail'),nameEl=document.getElementById('userName'),roleEl=document.getElementById('userRole'),avatarEl=document.getElementById('userAvatar');if(emailEl)emailEl.textContent=u.email||'';if(nameEl)nameEl.textContent=u.name||'Mi cuenta';if(roleEl)roleEl.textContent=u.role||'';if(avatarEl)avatarEl.src=u.photoUrl||'assets/CryApp_Logo.png'}
function renderNav(){if(!navEl)return;const groups=[['CRIADERO',['dashboard','birds','events','stats','breeding']],['GENEALOGÍA',['genealogy','familytree','inbreeding']],['COMUNIDAD',['messages','market']],['HERRAMIENTAS',['ai','reports','subscriptions','prohub']],['SISTEMA',['settings']]];navEl.innerHTML=groups.map(g=>`<div class="nav-group"><small>${g[0]}</small>${g[1].map(id=>{let m=modules.find(x=>x[0]===id);return m?`<button class="navbtn" data-route="${m[0]}"><span class="nav-icon-wrap"><img class="nav-icon" src="${m[1]}" alt=""></span><span>${m[2]}</span></button>`:''}).join('')}</div>`).join('');navEl.onclick=e=>{let b=e.target.closest('[data-route]');if(b)route(b.dataset.route)}}
function setHead(t,s){if(titleEl)titleEl.textContent=t;if(subtitleEl)subtitleEl.textContent=s;document.querySelectorAll('.navbtn').forEach(x=>x.classList.toggle('active',x.dataset.route===current))}
async function route(r){
  try{
    if(r!=='messages'&&typeof stopMsgPolling==='function')stopMsgPolling();
    current=r;
    const cryQuick=document.getElementById('cryAIQuick');if(cryQuick)cryQuick.hidden=(r==='ai'||document.getElementById('app')?.classList.contains('hidden'));
    const m=modules.find(x=>x[0]===r);
    setHead(r==='profile'?'Mi perfil':m?.[2]||r,'CryApp • '+(r==='profile'?'Cuenta y criadero':m?.[2]||''));
    if(!contentEl)throw Error('No se encontró el contenedor principal de CryApp');
    contentEl.innerHTML='<div class="route-loading"><span></span><b>Abriendo '+esc(r==='profile'?'Mi perfil':m?.[2]||r)+'…</b></div>';
    await new Promise(resolve=>requestAnimationFrame(()=>resolve()));
    if(r!=='subscriptions'&&cryLocked(r)){cryLockScreen(r);return;}
    const registry={dashboard,birds,genealogy,familytree,events,stats,breeding,inbreeding,reports,messages,market,prohub,settings,ai:cryAIRender};
    if(typeof profile==='function')registry.profile=profile;
    const fn=registry[r];
    if(r==='subscriptions')await crySubscriptionsPage(); else if(fn)await fn(); else externalModule(r,m?.[2]);
  }catch(e){
    console.error('CryApp route error',r,e);
    if(contentEl)contentEl.innerHTML='<div class="panel module-error"><span class="eyebrow">CRYAPP RECOVERY</span><h3>No se pudo abrir el módulo</h3><p>'+esc(e?.message||'Error inesperado')+'</p><button id="retryModule">Reintentar</button></div>';
    document.getElementById('retryModule')?.addEventListener('click',()=>route(r));
    toast(e?.message||'Error al abrir el módulo');
  }
}

