function cryTreeBirdById(id){return (cache.birds||[]).find(b=>String(b.birdId)===String(id))||null}
function cryTreeParent(b,side){if(!b)return null;return cryTreeBirdById(side==='father'?b.fatherId:b.motherId)}
function autoTreeCard(b,label,depth=0){
 if(!b)return `<article class="cry-tree-card missing"><div class="cry-tree-empty-icon">?</div><div><span>${esc(label)}</span><b>Sin registrar</b><small>Asigna padre o madre desde Ejemplares</small></div></article>`;
 return `<article class="cry-tree-card" data-tree-bird="${esc(b.birdId)}"><div class="cry-tree-photo"><img loading="lazy" decoding="async" src="${esc(pedigreeBirdPhoto(b))}" alt="${esc(b.name||'Ejemplar')}" onerror="this.src='assets/CryApp_Logo.png'"></div><div><span>${esc(label)}</span><b>${esc(b.name||b.plate||'Sin nombre')}</b><small>${b.plate?'Placa '+esc(b.plate):'Sin placa'} · ${esc(b.sex||'')}</small><small>${esc(b.farm||'')}</small></div></article>`;
}
function autoTreeBranch(b,label,depth=0,maxDepth=4,path=new Set()){
 const id=b?.birdId?String(b.birdId):'';
 if(id&&path.has(id))return `<div class="cry-tree-branch level-${depth}"><article class="cry-tree-card missing"><div class="cry-tree-empty-icon">!</div><div><span>${esc(label)}</span><b>Ciclo detectado</b><small>Revisa Padre/Madre en Ejemplares</small></div></article></div>`;
 const next=new Set(path);if(id)next.add(id);
 const card=autoTreeCard(b,label,depth);
 if(depth>=maxDepth||!b)return `<div class="cry-tree-branch level-${depth}">${card}</div>`;
 return `<div class="cry-tree-branch level-${depth}">${card}<div class="cry-tree-children">${autoTreeBranch(cryTreeParent(b,'father'),'PADRE',depth+1,maxDepth,next)}${autoTreeBranch(cryTreeParent(b,'mother'),'MADRE',depth+1,maxDepth,next)}</div></div>`;
}
function renderAutoTree(root,maxDepth=4){return autoTreeBranch(root,'EJEMPLAR PRINCIPAL',0,maxDepth,new Set())}
