async function stats(){let [sr,br,er]=await Promise.all([api('stats.summary'),api('birds.list'),api('events.list')]);let bs=Array.isArray(br.items)?br.items:[],ev=Array.isArray(er.items)?er.items:[];const calc=list=>{let wins=list.filter(x=>/victoria/i.test(x.result||'')).length,losses=list.filter(x=>/derrota/i.test(x.result||'')).length,draws=list.filter(x=>/empate/i.test(x.result||'')).length,total=list.length;return{wins,losses,draws,total,effectiveness:total?Math.round(wins/total*100):0}};const trabaNames=[...new Set(bs.map(b=>b.farm).filter(Boolean))];contentEl.innerHTML=`<div class="stats-filterbar"><button class="active" data-statmode="general">General</button><button data-statmode="bird">Por ejemplar</button><button data-statmode="farm">Por traba</button><select id="statsEntity" class="hidden"></select></div><div id="statsView"></div>`;function paint(mode='general',id=''){let data=sr,label='Estadísticas generales';if(mode==='bird'){let b=bs.find(x=>x.birdId===id)||bs[0];if(b){data=calc(ev.filter(x=>x.birdId===b.birdId));label=`Ejemplar: ${b.name||b.plate||'Sin nombre'}`}}else if(mode==='farm'){let farm=id||trabaNames[0]||'';let ids=new Set(bs.filter(x=>x.farm===farm).map(x=>x.birdId));data=calc(ev.filter(x=>ids.has(x.birdId)));label=`Traba: ${farm||'Sin traba'}`}let mx=Math.max(data.wins||0,data.losses||0,data.draws||0,1);statsView.innerHTML=`<div class="panel"><div class="toolbar"><div><span class="eyebrow">RENDIMIENTO</span><h3>${esc(label)}</h3></div></div><div class="grid"><div class="card"><span>Total</span><strong>${data.total||0}</strong></div><div class="card"><span>Victorias</span><strong>${data.wins||0}</strong></div><div class="card"><span>Derrotas</span><strong>${data.losses||0}</strong></div><div class="card"><span>Efectividad</span><strong>${data.effectiveness||0}%</strong></div></div><div class="chart-bars">${[['Victorias',data.wins||0],['Derrotas',data.losses||0],['Empates',data.draws||0]].map(x=>`<div><i style="height:${x[1]/mx*140}px"></i><b>${x[1]}</b><br><small>${x[0]}</small></div>`).join('')}</div></div>`}function mode(m){document.querySelectorAll('[data-statmode]').forEach(b=>b.classList.toggle('active',b.dataset.statmode===m));if(m==='general'){statsEntity.classList.add('hidden');paint()}else{statsEntity.classList.remove('hidden');statsEntity.innerHTML=m==='bird'?bs.map(b=>`<option value="${esc(b.birdId)}">${esc(b.name||b.plate||'Ejemplar')}</option>`).join(''):trabaNames.map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('');paint(m,statsEntity.value);statsEntity.onchange=()=>paint(m,statsEntity.value)}}document.querySelector('.stats-filterbar').onclick=e=>{let b=e.target.closest('[data-statmode]');if(b)mode(b.dataset.statmode)};mode('general')}
