async function inbreeding(){
 const bs=(await api('birds.list')).items||[],byId=new Map(bs.map(b=>[String(b.birdId),b]));
 const sexOf=b=>String(b.sex||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').trim().toLowerCase();
 const fathers=bs.filter(b=>['gallo','macho','male','rooster'].includes(sexOf(b)));
 const mothers=bs.filter(b=>['gallina','hembra','female','hen'].includes(sexOf(b)));
 contentEl.innerHTML=`<div class="panel"><h3>Consanguinidad</h3><p class="muted">Coeficiente esperado de consanguinidad de la descendencia al cruzar el padre y la madre seleccionados, según el pedigrí registrado.</p><div class="formgrid"><div class="field"><label for="ia">Padre</label><select id="ia"><option value="">Selecciona el padre</option>${fathers.map(b=>`<option value="${esc(b.birdId)}">${esc(b.name||b.plate||'Sin nombre')}${b.plate?' · '+esc(b.plate):''}</option>`).join('')}</select></div><div class="field"><label for="ib">Madre</label><select id="ib"><option value="">Selecciona la madre</option>${mothers.map(b=>`<option value="${esc(b.birdId)}">${esc(b.name||b.plate||'Sin nombre')}${b.plate?' · '+esc(b.plate):''}</option>`).join('')}</select></div><button id="calcI" ${fathers.length&&mothers.length?'':'disabled'}>Calcular coeficiente esperado</button></div>${fathers.length?'':'<p class="muted">No hay ejemplares machos disponibles para seleccionar como padre.</p>'}${mothers.length?'':'<p class="muted">No hay ejemplares hembras disponibles para seleccionar como madre.</p>'}<div id="iResult" aria-live="polite"></div></div>`;
 const ia=document.getElementById('ia'),ib=document.getElementById('ib'),result=document.getElementById('iResult');
 document.getElementById('calcI').onclick=()=>{
  const a=String(ia.value||''),b=String(ib.value||'');
  if(!a||!b){result.innerHTML='<div class="card">Selecciona un padre y una madre.</div>';return;}
  const parent=(id,side)=>{const x=byId.get(String(id));return x&&byId.has(String(x[side]||''))?String(x[side]):null};
  const memo=new Map(),visiting=new Set();let cycle=false;
  function phi(x,y){if(!x||!y)return 0;let key=[x,y].sort().join('|');if(memo.has(key))return memo.get(key);if(visiting.has(key)){cycle=true;return 0;}visiting.add(key);let v;
   if(x===y)v=(1+phi(parent(x,'fatherId'),parent(x,'motherId')))/2;
   else {let px=parent(x,'fatherId'),mx=parent(x,'motherId'),py=parent(y,'fatherId'),my=parent(y,'motherId');
    if(px||mx)v=(phi(px,y)+phi(mx,y))/2;
    else if(py||my)v=(phi(x,py)+phi(x,my))/2;
    else v=0;}
   visiting.delete(key);memo.set(key,v);return v;
  }
  const value=phi(a,b),ancestorSet=id=>{let found=new Set(),walk=(x,depth)=>{if(!x||depth>12||found.has(x))return;found.add(x);walk(parent(x,'fatherId'),depth+1);walk(parent(x,'motherId'),depth+1)};walk(id,0);return found};
  const aa=ancestorSet(a),ab=ancestorSet(b),common=[...aa].filter(x=>ab.has(x)).map(x=>byId.get(x)?.name||byId.get(x)?.plate||x);
  const relevant=new Set([...aa,...ab]);const missing=[...relevant].some(id=>{const bird=byId.get(id);return bird&&(!bird.fatherId||!bird.motherId)});
  result.innerHTML=cycle?'<div class="card">Se detectó una relación genealógica circular. Revisa los padres registrados.</div>':`<div class="card"><h3>Consanguinidad esperada de la descendencia</h3><strong class="cry-coefficient">${(value*100).toFixed(2)}%</strong><p class="cry-risk-label">${value===0?'Sin parentesco documentado':value<0.0625?'Parentesco registrado bajo':value<0.125?'Parentesco registrado moderado':'Parentesco registrado elevado'}</p><p>Antepasados compartidos: ${common.length?common.map(esc).join(', '):'Ninguno registrado'}</p><small class="muted">${missing?'Pedigrí incompleto: el porcentaje puede estar subestimado.':'Calculado a partir del pedigrí registrado.'} No equivale a una prueba genética. El resultado representa la consanguinidad esperada de la descendencia.</small></div>`;
 };
}
