async function downloadCryAppBackup(button){button.disabled=true;button.textContent='Preparando copia…';try{const server=await api('auth.backup');const pro={};for(const key of ['timeline','litters','repro','health','pens','inventory','trash'])pro[key]=proGet(key);pro.gallery=cry260Records(cry260.galleryKey);pro.calendar=cry260Records(cry260.calendarKey);try{pro.crosses=(await api('crosses.list')).items||[]}catch{pro.crosses=[]}const data={...server,datosLocales:pro};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='CryApp_Backup_'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia de seguridad descargada')}catch(e){toast(e.message||'No se pudo crear la copia')}finally{button.disabled=false;button.textContent='Descargar copia de seguridad'}}
