 contentEl.innerHTML=`<div class="panel"><span class="eyebrow">MEMBRESÍAS CRYAPP</span><h2>Desbloquea tu criadero</h2><p>Plan actual: <strong>${esc((st.plan||'free').toUpperCase())}</strong>${st.endsAt?' · Vence '+esc(new Date(st.endsAt).toLocaleDateString('es-DO')):''}</p><div class="cry-plan-grid"><div class="cry-plan-card"><span>GRATIS</span><h2>US$ 0.00</h2><p>Cuenta, perfil y vista de planes.</p><b>Herramientas restringidas</b></div>${(plans.items||[]).map(p=>`<div class="cry-plan-card"><span>${esc(p.name)}</span><h2>${esc(p.price_usd==null?'Precio no disponible':price(p.price_usd,'USD'))}</h2><p>${Number(p.duration_days)} días de acceso</p><p>${p.id==='premium'?'Todas las herramientas avanzadas':'Gestión de ejemplares, genealogía y comunidad'}</p><button data-plan="${esc(p.id)}" ${p.price_usd==null?'disabled title="El precio USD todavía no está configurado"':''}>${p.price_usd==null?'No disponible':'Solicitar '+esc(p.name)}</button></div>`).join('')}</div><h3>Mis solicitudes</h3><div class="cry-request-list">${(requests.items||[]).length?requests.items.map(x=>`<div>${esc(x.plan_id.toUpperCase())} · ${esc(x.currency==='USD'?price(x.amount_usd,'USD'):price(x.amount_dop,'DOP'))} · ${esc(x.status)} · ${esc(new Date(x.created_at).toLocaleDateString('es-DO'))}</div>`).join(''):'No tienes solicitudes todavía.'}</div><p class="muted">El pago se verifica manualmente. No compartas contraseñas ni información bancaria sensible.</p></div>`;
