const fabMain=document.getElementById('fabMain'),fabMenu=document.getElementById('fabMenu');if(fabMain&&fabMenu){fabMain.onclick=()=>fabMenu.classList.toggle('show');fabMenu.onclick=e=>{let b=e.target.closest('[data-fab]');if(b){fabMenu.classList.remove('show');route(b.dataset.fab)}}}


/* CryApp 2.6.0 - non-invasive client features */
const cry260={page:0,pageSize:36,layout:localStorage.getItem('cry260_layout')||'grid',galleryKey:'cry260_gallery',calendarKey:'cry260_calendar'};
function cry260Records(key){try{const x=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(x)?x:[]}catch{return[]}}
function cry260Store(key,items){try{localStorage.setItem(key,JSON.stringify(items))}catch(e){toast('Sin espacio local disponible')}}
function cry260Safe(s){return esc(String(s??''))}
function cry260Qr(text){return 'https://api.qrserver.com/v1/create-qr-code/?size=210x210&data='+encodeURIComponent(text)}
function cry260OpenQR(id){const b=(cache.birds||[]).find(x=>String(x.birdId)===String(id));if(!b)return;const url=location.origin+location.pathname+'#ejemplar='+encodeURIComponent(id);const layer=document.createElement('div');layer.className='cry260-overlay';layer.innerHTML=`<section class="cry260-dialog"><button class="secondary" data-close>✕ Cerrar</button><h2>QR del ejemplar</h2><p>${cry260Safe(b.name||b.plate)}</p><img class="cry260-qr" src="${cry260Qr(url)}" alt="QR del ejemplar"><p class="muted">Identificador: ${cry260Safe(id)}. El enlace requiere iniciar sesión para consultar datos privados.</p><button data-print>Imprimir QR</button></section>`;document.body.append(layer);layer.onclick=e=>{if(e.target===layer||e.target.closest('[data-close]'))layer.remove();if(e.target.closest('[data-print]'))window.print()}}
function cry260Gallery(id){const b=(cache.birds||[]).find(x=>String(x.birdId)===String(id));if(!b)return;const layer=document.createElement('div');layer.className='cry260-overlay';const all=()=>cry260Records(cry260.galleryKey).filter(x=>x.id===id);function draw(){layer.innerHTML=`<section class="cry260-dialog"><div class="toolbar"><h2>Galería · ${cry260Safe(b.name)}</h2><button class="secondary" data-close>✕</button></div><p class="muted">Galería local de este navegador; las fotos adicionales no se sincronizan con Drive.</p><div class="cry260-gallery">${[...(b.photoUrl?[{url:b.photoUrl,main:true}]:[]),...all()].map((x,i)=>`<div><img loading="lazy" src="${cry260Safe(x.url)}"><div>${x.main?'Foto principal':`<button data-remove="${i-Number(!!b.photoUrl)}" class="secondary">Eliminar</button>`}</div></div>`).join('')}</div><label class="cry260-upload">Añadir fotografía <input type="file" id="cry260GalleryFile" accept="image/*"></label></section>`;layer.querySelector('#cry260GalleryFile').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;if(f.size>4000000){toast('Elige una imagen menor de 4 MB');return}let i=new Image();i.src=URL.createObjectURL(f);await i.decode();let c=document.createElement('canvas'),scale=Math.min(1,900/Math.max(i.width,i.height));c.width=Math.round(i.width*scale);c.height=Math.round(i.height*scale);c.getContext('2d').drawImage(i,0,0,c.width,c.height);URL.revokeObjectURL(i.src);let records=cry260Records(cry260.galleryKey);records.push({id,url:c.toDataURL('image/jpeg',.68)});cry260Store(cry260.galleryKey,records);draw()}}draw();layer.onclick=e=>{if(e.target===layer||e.target.closest('[data-close]'))layer.remove();const rm=e.target.closest('[data-remove]');if(rm){const own=all(),chosen=own[Number(rm.dataset.remove)];cry260Store(cry260.galleryKey,cry260Records(cry260.galleryKey).filter(x=>x!==chosen));draw()}};document.body.append(layer)}
function cry260Calendar(){const layer=document.createElement('div');layer.className='cry260-overlay';const render=()=>{const events=cry260Records(cry260.calendarKey).sort((a,b)=>a.date.localeCompare(b.date));layer.innerHTML=`<section class="cry260-dialog"><div class="toolbar"><h2>Calendario del criadero</h2><button data-close class="secondary">✕</button></div><p class="muted">Agenda privada guardada en este navegador. Los eventos existentes del servidor siguen en su sección original.</p><form id="cry260EventForm" class="cry260-event-form"><input name="date" type="date" required><input name="title" placeholder="Nacimiento, revisión, incubación…" maxlength="90" required><button>Guardar</button></form><div class="cry260-event-list">${events.map((x,i)=>`<div class="cry260-event"><b>${cry260Safe(x.date)}</b><span>${cry260Safe(x.title)}</span><button class="secondary" data-remove="${i}">Eliminar</button></div>`).join('')||'<p class="muted">Sin eventos locales.</p>'}</div></section>`;layer.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=cry260Records(cry260.calendarKey);v.push({date:String(f.get('date')),title:String(f.get('title'))});cry260Store(cry260.calendarKey,v);render()}};render();layer.onclick=e=>{if(e.target===layer||e.target.closest('[data-close]'))layer.remove();const b=e.target.closest('[data-remove]');if(b){const a=cry260Records(cry260.calendarKey).sort((x,y)=>x.date.localeCompare(y.date));a.splice(Number(b.dataset.remove),1);cry260Store(cry260.calendarKey,a);render()}};document.body.append(layer)}
function cry260Enhance(){if(!document.querySelector('#cry260Tools')){let bar=document.createElement('div');bar.id='cry260Tools';bar.className='cry260-tools';bar.innerHTML='<button id="cry260Calendar" class="secondary">▦ Calendario</button><button id="cry260Layout" class="secondary">▦ Vista compacta</button>';contentEl?.prepend(bar);bar.querySelector('#cry260Calendar').onclick=cry260Calendar;bar.querySelector('#cry260Layout').onclick=()=>{cry260.layout=cry260.layout==='grid'?'compact':'grid';localStorage.setItem('cry260_layout',cry260.layout);cry260ApplyLayout()}}cry260ApplyLayout();document.querySelectorAll('.bird-card').forEach(card=>{if(card.querySelector('.cry260-card-actions'))return;const id=card.querySelector('[data-view]')?.dataset.view;if(!id)return;let div=document.createElement('div');div.className='cry260-card-actions';div.innerHTML=`<button class="secondary" data-qr="${cry260Safe(id)}">QR</button><button class="secondary" data-gallery="${cry260Safe(id)}">Galería</button>`;card.append(div)});if(!contentEl.dataset.cry260Click){contentEl.dataset.cry260Click='1';contentEl.addEventListener('click',e=>{let qr=e.target.closest('[data-qr]'),gal=e.target.closest('[data-gallery]');if(qr)cry260OpenQR(qr.dataset.qr);if(gal)cry260Gallery(gal.dataset.gallery)})}}
function cry260ApplyLayout(){contentEl?.classList.toggle('cry260-compact',cry260.layout==='compact');const b=document.getElementById('cry260Layout');if(b)b.textContent=cry260.layout==='compact'?'▦ Vista cómoda':'▦ Vista compacta'}
(function(){if(typeof MutationObserver==='undefined')return;let pending=false;const mo=new MutationObserver(()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;if(contentEl?.querySelector('.panel, .hero-pro'))cry260Enhance()})});const start=()=>{if(contentEl)mo.observe(contentEl,{childList:true,subtree:false})};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start()})();

// V2.6.1: recuperación desde el login
(function(){
 const el=id=>document.getElementById(id),form=el('resetForm');if(!form)return;
 el('showForgot').addEventListener('click',()=>{form.classList.remove('hidden');el('loginForm').classList.add('hidden');el('loginIntro').classList.add('hidden');el('showForgot').classList.add('hidden');el('showRegister').classList.add('hidden');el('authSeparator').classList.add('hidden');el('cry-auth-features').classList.add('hidden');el('resetBackTop').classList.remove('hidden');el('registerForm')?.classList.add('hidden');el('resetEmail').value=el('email')?.value||'';el('resetEmail').focus()});
 const closeReset=()=>{form.classList.add('hidden');el('loginForm').classList.remove('hidden');['loginIntro','showForgot','showRegister','authSeparator','cry-auth-features'].forEach(id=>el(id)?.classList.remove('hidden'));el('resetBackTop').classList.add('hidden');el('resetEmailStep').classList.remove('hidden');el('resetConfirmFields').classList.add('hidden');el('resetStatus').textContent=''};el('resetClose').addEventListener('click',closeReset);el('resetBackTop').addEventListener('click',closeReset);
 el('resetRequestBtn').addEventListener('click',async()=>{const btn=el('resetRequestBtn'),status=el('resetStatus');btn.disabled=true;status.textContent='Enviando solicitud…';try{const r=await api('auth.reset.request',{email:el('resetEmail').value.trim()});status.textContent=r.message||'Revisa tu correo.';el('resetConfirmFields').classList.remove('hidden');el('resetEmailStep').classList.add('hidden')}catch(e){status.textContent=e.message}finally{btn.disabled=false}});
 el('resetConfirmBtn').addEventListener('click',async()=>{const btn=el('resetConfirmBtn'),status=el('resetStatus');btn.disabled=true;try{if(el('resetNewPassword').value!==el('resetRepeatPassword').value)throw Error('Las contraseñas no coinciden');const r=await api('auth.reset.confirm',{email:el('resetEmail').value.trim(),code:el('resetCode').value.trim(),newPassword:el('resetNewPassword').value});status.textContent=r.message||'Contraseña actualizada';el('resetNewPassword').value='';if(r.ok){el('email').value=el('resetEmail').value;setTimeout(closeReset,1300)}}catch(e){status.textContent=e.message}finally{btn.disabled=false}});
})();

/* CryApp 2.7.5: acceso rápido a CryAI; sin controles flotantes de efectos. */
(function(){
 function init(){
   document.getElementById('cryVisualToggle')?.remove();
   if(document.getElementById('cryAIQuick'))return;
   const btn=document.createElement('button');btn.type='button';btn.id='cryAIQuick';btn.className='cry-ai-quick';btn.textContent='✦ CryAI';btn.title='Abrir asistente CryAI';
   btn.onclick=()=>{if(typeof route==='function')route('ai')};
   document.body.appendChild(btn);
   const observer=new MutationObserver(()=>{const app=document.getElementById('app');btn.hidden=!app||app.classList.contains('hidden')||(typeof current!=='undefined'&&current==='ai')});
   observer.observe(document.getElementById('app')||document.body,{attributes:true,attributeFilter:['class']});
   const oldRoute=window.route; // navegación normal conserva sus funciones
   btn.hidden=document.getElementById('app')?.classList.contains('hidden')!==false;
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

// CryAI OpenAI PRO - chat conectado exclusivamente al servidor GS.
let cryAIChat=[];
async function cryAIRender(){
 contentEl.innerHTML=`<div class="cryai-wrap"><div class="cryai-heading"><div class="cryai-mark">✦</div><div><h2>CryAI · Asistente inteligente</h2><p>Consultas sobre tu criadero, registros, genealogía y bienestar animal.</p></div></div><div id="cryaiChat" class="cryai-chat"><div class="cryai-message assistant">¡Hola! Soy CryAI. Puedo ayudarte con tus ejemplares y los registros de tu criadero. ¿Qué deseas consultar?</div></div><form id="cryaiForm" class="cryai-form"><textarea id="cryaiQuestion" rows="2" maxlength="1800" placeholder="Escribe tu pregunta a CryAI…" required></textarea><div class="cryai-tools"><label><input id="cryaiContext" type="checkbox" checked> Incluir mis ejemplares registrados</label><button id="cryaiSend" type="submit">Enviar ✦</button></div></form><p class="cryai-note">CryAI puede equivocarse. Para problemas de salud, consulta a un veterinario. Tu consulta se envía a OpenAI a través del servidor.</p></div>`;
 const form=document.getElementById('cryaiForm'), q=document.getElementById('cryaiQuestion'), chat=document.getElementById('cryaiChat'), btn=document.getElementById('cryaiSend');
 function add(text,who){let el=document.createElement('div');el.className='cryai-message '+who;el.textContent=text;chat.appendChild(el);chat.scrollTop=chat.scrollHeight;return el}
 form.onsubmit=async e=>{e.preventDefault();let question=q.value.trim();if(!question)return;q.value='';add(question,'user');btn.disabled=true;btn.textContent='Consultando…';let wait=add('CryAI está pensando…','assistant');try{let context=[];if(document.getElementById('cryaiContext').checked){try{let birds=await api('birds.list');context=(birds.items||[]).slice(0,40).map(b=>({nombre:b.name,placa:b.plate,sexo:b.sex,nacimiento:b.birthDate,padre:b.fatherId,madre:b.motherId}));}catch(e){console.warn('CryAI contexto no disponible',e)}}let result=await api('ai.ask',{question,history:cryAIChat.slice(-8),birds:context});wait.textContent=result.answer||'No recibí respuesta.';cryAIChat.push({role:'user',content:question},{role:'assistant',content:result.answer||''});if(cryAIChat.length>12)cryAIChat=cryAIChat.slice(-12)}catch(err){wait.textContent=(/Acción API no válida: ai\.ask/i.test(err.message||'')?'El servidor de CryApp no tiene activada la función CryAI. Actualiza el archivo GS incluido y vuelve a publicar una versión nueva en Implementar → Gestionar implementaciones.':'No se pudo consultar CryAI: '+(err.message||'Error de conexión'))}finally{btn.disabled=false;btn.textContent='Enviar ✦';chat.scrollTop=chat.scrollHeight}};
}
